"""Hai mẫu Word đúng nguyên bản khách/cơ quan đưa, mở ra là in được: chỉ thay SỐ LIỆU ngay trên chữ có sẵn, không thêm, không sửa kiểu chữ, khung, căn lề.

- Mẫu số 22 (Thông báo hoàn thành thủ tục hải quan nhập khẩu tại chỗ) của Arizon: một thông báo cho một lô + trang ghi chú của mẫu.
- Bảng kê sản phẩm gỗ xuất khẩu (bảng kê lâm sản) của Tesa: chỉ dùng cho lô hàng pallet.

Thay số liệu theo từng đoạn chữ: chỉ ô chữ (run) chứa số cũ bị đổi, các ô chữ khác (chỉ số trên, chữ đậm...) giữ nguyên.
"""

import base64
import io
import re
import zipfile
from html import unescape
from xml.sax.saxutils import escape

_T = re.compile(r"(<w:t(?: [^>]*)?>)(.*?)(</w:t>)", re.S)
_P = re.compile(r"<w:p[ >].*?</w:p>", re.S)
_TOK = re.compile(r"<w:tbl>|</w:tbl>|<w:p[ >/]|</w:p>|<w:sectPr[ >]|</w:sectPr>")


def template_bytes(b64):
    return base64.b64decode(b64)


def _document_xml(docx):
    with zipfile.ZipFile(io.BytesIO(docx)) as z:
        return z.read("word/document.xml").decode("utf-8")


def _with_document_xml(docx, xml):
    out = io.BytesIO()
    with zipfile.ZipFile(io.BytesIO(docx)) as src, zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as dst:
        for item in src.infolist():
            dst.writestr(item, xml.encode("utf-8") if item.filename == "word/document.xml" else src.read(item.filename))
    return out.getvalue()


def split_body(xml):
    """(đầu, [khối cấp cao nhất của thân văn bản: đoạn, bảng, sectPr], cuối)."""
    a = xml.index("<w:body>") + len("<w:body>")
    b = xml.rindex("</w:body>")
    body, blocks, i = xml[a:b], [], 0
    while i < len(body):
        m = _TOK.search(body, i)
        if not m:
            break
        start, tag = m.start(), m.group(0)
        if tag == "<w:tbl>":
            depth, j = 1, m.end()
            while depth:
                n = _TOK.search(body, j)
                depth += (n.group(0) == "<w:tbl>") - (n.group(0) == "</w:tbl>")
                j = n.end()
            end = j
        elif tag.startswith("<w:p"):
            gt = body.index(">", m.start())
            end = gt + 1 if body[gt - 1] == "/" else body.index("</w:p>", gt) + len("</w:p>")
        else:
            end = body.index("</w:sectPr>", m.start()) + len("</w:sectPr>")
        blocks.append(body[start:end])
        i = end
    return xml[:a], blocks, xml[b:]


def para_text(p):
    return "".join(unescape(t) for _o, t, _c in _T.findall(p))


def sub_in_paragraph(p, old, new):
    """Đổi chữ `old` thành `new` trong đoạn `p` (có thể nằm trên nhiều ô chữ): chỉ các ô chữ chứa `old` bị đổi."""
    spans = [(m.start(2), m.end(2), unescape(m.group(2))) for m in _T.finditer(p)]
    full = "".join(t for _a, _b, t in spans)
    k = full.find(old)
    if k < 0:
        return p
    end, pos, out, done = k + len(old), 0, [], False
    pieces = []
    for a, b, t in spans:
        lo, hi = pos, pos + len(t)
        pos = hi
        if hi <= k or lo >= end:
            pieces.append((a, b, None))
            continue
        before, after = t[:max(0, k - lo)], t[max(0, end - lo):]
        pieces.append((a, b, before + (new if not done else "") + after))
        done = True
    res, last = [], 0
    for a, b, rep in pieces:
        res.append(p[last:a])
        res.append(p[a:b] if rep is None else escape(rep))
        last = b
    res.append(p[last:])
    out = "".join(res)
    return out.replace("<w:t>", '<w:t xml:space="preserve">') if "<w:t>" in out else out


def sub_everywhere(xml_block, pairs):
    """Áp dụng các cặp (cũ, mới) cho từng đoạn trong khối; mỗi cặp chỉ đổi ở đoạn có chữ cũ."""
    def one(m):
        p = m.group(0)
        for old, new in pairs:
            p = sub_in_paragraph(p, old, new)
        return p
    return _P.sub(one, xml_block)


def _dots(x):
    """Số kiểu Việt Nam (chấm ngăn nghìn, phẩy thập phân, tối đa 3 số lẻ): 3780 -> '3.780'."""
    x = float(x or 0)
    s = f"{x:,.3f}".rstrip("0").rstrip(".") if x != int(x) else f"{int(x):,}"
    return s.replace(",", "§").replace(".", ",").replace("§", ".")


def _replace_exact(xml_block, old, new):
    """Đổi chữ của những đoạn mà TOÀN BỘ chữ đúng bằng `old`."""
    return _P.sub(lambda m: sub_in_paragraph(m.group(0), old, new) if para_text(m.group(0)).strip() == old else m.group(0), xml_block)


def m22_arizon(d, tk_xuat, tk_nhap):
    """Mẫu số 22 cho một lô. `d`: ngày chứng từ (datetime.date). Số tờ khai chưa có thì để dấu chấm cho người ký điền tay."""
    docx = template_bytes(M22_ARIZON_B64)
    head, blocks, tail = split_body(_document_xml(docx))
    dots = "............"
    pairs = [("Số: ", "08/2026", f"{d.month:02d}/{d.year}"), ("Bắc Ninh", "08 tháng 8 năm 2026", f"{d.day:02d} tháng {d.month} năm {d.year}"),
             ("- Số, ngày tờ khai: 3088", "308829221060", str(tk_xuat or "").strip() or dots),
             ("- Số, ngày tờ khai: 1085", "108512041960", str(tk_nhap or "").strip() or dots),
             ("Hợp đồng nhập khẩu:", "8/8/2026", f"{d.day}/{d.month}/{d.year}")]

    def one(m):
        p, txt = m.group(0), para_text(m.group(0))
        for ctx, old, new in pairs:
            if txt.startswith(ctx) or (ctx in txt and ctx.startswith("Hợp")):
                p = sub_in_paragraph(p, old, new)
        return p
    body = _P.sub(one, "".join(blocks))
    return _with_document_xml(docx, head + body + tail)


def bkls_tesa(d, items):
    """Bảng kê sản phẩm gỗ xuất khẩu (pallet). `items`: [{"code", "qty", "weight"}]; mỗi mặt hàng một dòng, có dòng tổng."""
    docx = template_bytes(BKLS_TESA_B64)
    head, blocks, tail = split_body(_document_xml(docx))
    out = []
    for b in blocks:
        txt = para_text(b)
        if b.startswith("<w:tbl>") and "Pallet bằng gỗ" in txt and "Tổng:" in txt:
            rows = re.findall(r"<w:tr[ >].*?</w:tr>", b, re.S)
            data_tpl, total = rows[2], rows[4]
            new_rows = []
            for i, it in enumerate(items, 1):
                r = _replace_exact(data_tpl, "1", str(i))
                code = str(it.get("code") or "").strip()
                if code:
                    r = _replace_exact(r, "39776-90000-00", code)
                r = _replace_exact(r, "180", _dots(it["qty"]))
                r = _replace_exact(r, "3.780", _dots(it["weight"]))
                new_rows.append(r)
            total = _replace_exact(total, "360", _dots(sum(float(it["qty"]) for it in items)))
            total = _replace_exact(total, "7.560", _dots(sum(float(it["weight"]) for it in items)))
            first = b.index(rows[2])
            b = b[:first] + "".join(new_rows) + total + b[b.index(rows[4]) + len(rows[4]):]
        else:
            b = sub_everywhere(b, [("2026.02.11", f"{d.year}.{d.day:02d}.{d.month:02d}"), ("02  tháng  11 năm 2026", f"{d.day:02d}  tháng  {d.month} năm {d.year}")])
        out.append(b)
    return _with_document_xml(docx, head + "".join(out) + tail)


